message.content:
{
  "candidate_edge_types": [
    {
      "name": "PROBES_ENVIRONMENT_TO_INFORM_PLANNING",
      "definition": "An agent runs diagnostic commands to gather facts about the execution environment before deciding how to proceed with the task.",
      "source_description": "An initial agent planning state that lacks knowledge about the execution environment.",
      "target_description": "A diagnostic command whose purpose is to gather environment facts (OS, available tools, package sources, existing files)."
    },
    {
      "name": "MODIFIES_CONFIGURATION_TO_ENABLE_BLOCKED_OPERATION",
      "definition": "An agent alters a tool or environment configuration in response to a discovered limitation that otherwise blocks a required operation.",
      "source_description": "An observed environment or tool configuration limitation that prevents a required operation.",
      "target_description": "An action that modifies configuration so the blocked operation becomes possible."
    },
    {
      "name": "EXAMINES_CONFIGURATION_TO_DERIVE_ACTION_PARAMETERS",
      "definition": "An agent inspects a configuration or build-definition artifact and uses the discovered settings to choose parameters for a subsequent execution action.",
      "source_description": "A configuration or build-definition artifact examined by the agent to understand its settings.",
      "target_description": "A subsequent action whose parameters are derived from the examined configuration."
    },
    {
      "name": "WAITS_FOR_PENDING_OPERATION_TO_COMPLETE",
      "definition": "An agent issues a follow-up action to wait for or poll a previously started long-running operation that has not yet produced observable output.",
      "source_description": "An observation indicating that a previously initiated operation has not yet completed.",
      "target_description": "A subsequent action that waits for or polls the completion of that operation."
    },
    {
      "name": "VERIFIES_RESULT_SATISFIES_REQUIREMENT",
      "definition": "A subsequent action independently checks that an artifact, binary, or command result produced earlier conforms to a stated requirement.",
      "source_description": "A previously produced artifact, binary, or command result.",
      "target_description": "A verification action that checks a required property of that artifact or result."
    },
    {
      "name": "CONFIRMS_TASK_COMPLETION_AFTER_VERIFIED_CRITERIA",
      "definition": "An agent declares the task finished after earlier verification steps have confirmed the required success criteria.",
      "source_description": "One or more earlier verification results confirming required success criteria.",
      "target_description": "A task-completion declaration action."
    }
  ]
}

